def mirror_tile(I):
    H=[row[::-1] for row in I]          # horizontal mirror
    V=I[::-1]                           # vertical mirror
    R=[row[::-1] for row in V]          # 180 rotation
    blocks=[[I,H,I],[V,R,V],[I,H,I]]
    out=[]
    for A in range(3):
        for r in range(3):
            out.append(sum((blocks[A][B][r] for B in range(3)),[]))
    return out
